    12→
    13→interface ComparisonResult {
    14→  deputyA: DeputyDetail;
    15→  deputyB: DeputyDetail;
    16→  metrics: ComparisonMetric[];
    17→  winsA: number;
    18→  winsB: number;
    19→  ties: number;
