    23→
    24→export function useCompareDeputies(
    25→  deputyA: DeputyDetail | null,
    26→  deputyB: DeputyDetail | null
    27→): ComparisonResult | null {
    28→  return useMemo(() => {
    29→    if (!deputyA || !deputyB) return null;
    30→
    31→    const metrics: ComparisonMetric[] = [
    32→      {
    33→        label: 'Pontuacao Global',
    34→        valueA: deputyA.work_score,
    35→        valueB: deputyB.work_score,
    36→        winnerA: deputyA.work_score > deputyB.work_score,
    37→        winnerB: deputyB.work_score > deputyA.work_score,
    38→        tie: deputyA.work_score === deputyB.work_score,
    39→      },
    40→      {
    41→        label: 'Propostas',
    42→        valueA: deputyA.proposal_count,
    43→        valueB: deputyB.proposal_count,
    44→        winnerA: deputyA.proposal_count > deputyB.proposal_count,
    45→        winnerB: deputyB.proposal_count > deputyA.proposal_count,
    46→        tie: deputyA.proposal_count === deputyB.proposal_count,
    47→      },
    48→      {
    49→        label: 'Intervencoes',
    50→        valueA: deputyA.intervention_count,
    51→        valueB: deputyB.intervention_count,
    52→        winnerA: deputyA.intervention_count > deputyB.intervention_count,
    53→        winnerB: deputyB.intervention_count > deputyA.intervention_count,
    54→        tie: deputyA.intervention_count === deputyB.intervention_count,
    55→      },
    56→      {
    57→        label: 'Perguntas',
    58→        valueA: deputyA.question_count,
    59→        valueB: deputyB.question_count,
    60→        winnerA: deputyA.question_count > deputyB.question_count,
    61→        winnerB: deputyB.question_count > deputyA.question_count,
    62→        tie: deputyA.question_count === deputyB.question_count,
    63→      },
    64→      {
    65→        label: 'Ranking Nacional',
    66→        valueA: deputyA.national_rank,
    67→        valueB: deputyB.national_rank,
    68→        winnerA: deputyA.national_rank < deputyB.national_rank, // Lower rank is better
    69→        winnerB: deputyB.national_rank < deputyA.national_rank,
    70→        tie: deputyA.national_rank === deputyB.national_rank,
    71→      },
    72→    ];
    73→
    74→    const winsA = metrics.filter((m) => m.winnerA).length;
    75→    const winsB = metrics.filter((m) => m.winnerB).length;
    76→    const ties = metrics.filter((m) => m.tie).length;
    77→
    78→    let winner: 'A' | 'B' | 'tie';
    79→    if (winsA > winsB) {
    80→      winner = 'A';
    81→    } else if (winsB > winsA) {
    82→      winner = 'B';
    83→    } else {
    84→      // Use work_score as tiebreaker
    85→      if (deputyA.work_score > deputyB.work_score) {
    86→        winner = 'A';
    87→      } else if (deputyB.work_score > deputyA.work_score) {
    88→        winner = 'B';
    89→      } else {
    90→        winner = 'tie';
    91→      }
    92→    }
    93→
    94→    return {
    95→      deputyA,
    96→      deputyB,
    97→      metrics,
    98→      winsA,
    99→      winsB,
   100→      ties,
   101→      winner,
   102→      scoreDifference: Math.abs(deputyA.work_score - deputyB.work_score),
   103→    };
   104→  }, [deputyA, deputyB]);
   105→}
   106→

