     1→import { useMemo } from 'react';
     2→import type { DistrictStats } from '../../lib/supabase';
     3→
     4→export interface DistrictComparisonMetric {
     5→  label: string;
     6→  valueA: number;
     7→  valueB: number;
     8→  winnerA: boolean;
     9→  winnerB: boolean;
    10→  tie: boolean;
    11→  higherIsBetter: boolean;
    12→}
    13→
    14→export interface DistrictComparisonResult {
    15→  districtA: DistrictStats;
    16→  districtB: DistrictStats;
    17→  metrics: DistrictComparisonMetric[];
    18→  winsA: number;
    19→  winsB: number;
    20→  ties: number;
    21→  winner: 'A' | 'B' | 'tie';
    22→}
    23→
    24→function compare(
    25→  a: number | null,
    26→  b: number | null,
    27→  higherIsBetter = true
    28→): { winnerA: boolean; winnerB: boolean; tie: boolean } {
    29→  const valA = a ?? 0;
    30→  const valB = b ?? 0;
    31→
    32→  if (valA === valB) {
    33→    return { winnerA: false, winnerB: false, tie: true };
    34→  }
    35→
    36→  const aWins = higherIsBetter ? valA > valB : valA < valB;
    37→  return {
    38→    winnerA: aWins,
    39→    winnerB: !aWins,
    40→    tie: false,
    41→  };
    42→}
    43→
    44→export function useCompareDistricts(
    45→  districtA: DistrictStats | null,
    46→  districtB: DistrictStats | null
    47→): DistrictComparisonResult | null {
    48→  return useMemo(() => {
    49→    if (!districtA || !districtB) return null;
    50→
    51→    const metricsConfig: {
    52→      label: string;
    53→      getA: () => number | null;
    54→      getB: () => number | null;
    55→      higherIsBetter: boolean;
    56→    }[] = [
    57→      {
    58→        label: 'Pontuacao Media',
    59→        getA: () => districtA.avg_work_score,
    60→        getB: () => districtB.avg_work_score,
    61→        higherIsBetter: true,
    62→      },
    63→      {
    64→        label: 'Assiduidade Media',
    65→        getA: () => districtA.avg_attendance_rate,
    66→        getB: () => districtB.avg_attendance_rate,
    67→        higherIsBetter: true,
    68→      },
    69→      {
    70→        label: 'Deputados Ativos',
    71→        getA: () => districtA.active_deputies,
    72→        getB: () => districtB.active_deputies,
    73→        higherIsBetter: true,
    74→      },
    75→    ];
    76→
    77→    const metrics: DistrictComparisonMetric[] = metricsConfig.map((m) => {
    78→      const valueA = m.getA() ?? 0;
    79→      const valueB = m.getB() ?? 0;
    80→      const { winnerA, winnerB, tie } = compare(valueA, valueB, m.higherIsBetter);
    81→      return {
    82→        label: m.label,
    83→        valueA,
    84→        valueB,
    85→        winnerA,
    86→        winnerB,
    87→        tie,
    88→        higherIsBetter: m.higherIsBetter,
    89→      };
    90→    });
    91→
    92→    const winsA = metrics.filter((m) => m.winnerA).length;
    93→    const winsB = metrics.filter((m) => m.winnerB).length;
    94→    const ties = metrics.filter((m) => m.tie).length;
    95→
    96→    let winner: 'A' | 'B' | 'tie';
    97→    if (winsA > winsB) {
    98→      winner = 'A';
    99→    } else if (winsB > winsA) {
   100→      winner = 'B';
   101→    } else {
   102→      winner = 'tie';
   103→    }
   104→
   105→    return {
   106→      districtA,
   107→      districtB,
   108→      metrics,
   109→      winsA,
   110→      winsB,
   111→      ties,
   112→      winner,
   113→    };
   114→  }, [districtA, districtB]);
   115→}
